-- ==============================================================================
-- LV SPORTS CARNIVAL - COMPLETE SUPABASE DATABASE SETUP & SEED
-- Run this script in your Supabase SQL Editor:
-- https://supabase.com/dashboard/project/cqkhfskjxeghcmknvibs/sql/new
-- ==============================================================================

-- 1. CARNIVAL STATE TABLE (for live TV real-time sync)
CREATE TABLE IF NOT EXISTS public.carnival_state (
  id TEXT PRIMARY KEY,
  data JSONB NOT NULL,
  updated_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- 2. TEAMS TABLE
CREATE TABLE IF NOT EXISTS public.teams (
  id TEXT PRIMARY KEY,
  code TEXT NOT NULL,
  name TEXT NOT NULL,
  color TEXT NOT NULL,
  secondary_color TEXT,
  captain TEXT,
  vice_captain TEXT,
  mascot TEXT
);

-- 3. MEMBERS TABLE
CREATE TABLE IF NOT EXISTS public.members (
  id TEXT PRIMARY KEY,
  team_id TEXT NOT NULL REFERENCES public.teams(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  role TEXT,
  jersey_number INTEGER
);

-- 4. GAMES TABLE
CREATE TABLE IF NOT EXISTS public.games (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  category TEXT NOT NULL,
  icon TEXT,
  status TEXT DEFAULT 'upcoming',
  scheduled_time TEXT,
  venue TEXT,
  first_place_team_id TEXT REFERENCES public.teams(id),
  second_place_team_id TEXT REFERENCES public.teams(id),
  notes TEXT
);

-- 5. ANNOUNCEMENTS TABLE
CREATE TABLE IF NOT EXISTS public.announcements (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  message TEXT NOT NULL,
  category TEXT DEFAULT 'general',
  active BOOLEAN DEFAULT true,
  created_at TEXT
);

-- ENABLE ROW LEVEL SECURITY (RLS) FOR ALL TABLES
ALTER TABLE public.carnival_state ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.teams ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.members ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.games ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.announcements ENABLE ROW LEVEL SECURITY;

-- CREATE PUBLIC READ/WRITE POLICIES
DO $$ 
DECLARE
  tbl TEXT;
BEGIN
  FOR tbl IN SELECT unnest(ARRAY['carnival_state', 'teams', 'members', 'games', 'announcements']) LOOP
    EXECUTE format('DROP POLICY IF EXISTS "Public read on %I" ON public.%I;', tbl, tbl);
    EXECUTE format('CREATE POLICY "Public read on %I" ON public.%I FOR SELECT TO public USING (true);', tbl, tbl);
    EXECUTE format('DROP POLICY IF EXISTS "Public write on %I" ON public.%I;', tbl, tbl);
    EXECUTE format('CREATE POLICY "Public write on %I" ON public.%I FOR ALL TO public USING (true) WITH CHECK (true);', tbl, tbl);
  END LOOP;
END $$;

-- ENABLE REALTIME ON TABLES
DO $$
DECLARE
  tbl TEXT;
BEGIN
  FOR tbl IN SELECT unnest(ARRAY['carnival_state', 'games', 'announcements']) LOOP
    IF NOT EXISTS (
      SELECT 1 FROM pg_publication_tables 
      WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = tbl
    ) THEN
      EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I;', tbl);
    END IF;
  END LOOP;
END $$;

